    constructor(@Optional() @Inject(forwardRef(() => Dep)) readonly dep?: Dep) {}
}

describe('optional injection', () => {
    it('resolves undefined when missing', async () => {
        const mod = await Test.createTestingModule({ providers: [Svc] }).compile();
        const svc = mod.get<Svc>(Svc);
        expect(svc).toBeDefined();
        expect(svc.dep).toBeUndefined();
