    it('works with useMocker missing token', async () => {
        const mod = await Test.createTestingModule({ providers: [Svc] })
            .useMocker(() => undefined)
            .compile();
        const svc = mod.get<Svc>(Svc);
        expect(svc.dep).toBeUndefined();
    });
});
