/**
 * Hydrates the offering a customer is attached to.
 * Customers are not required to carry an offering while the migration away from services is in progress.
 */
private async findOfferingForCustomer({ businessID, offeringId }): Promise<ReadOfferingResponseData | undefined> {
    if (!offeringId) {
        return undefined;
    }
    try {
        const {
            data: [offering],
        } = await this.offeringService.findOne({ businessID, offeringId });
        return offering;
    } catch (error) {
        CustomerService.logger.error(
            `Could not hydrate offering: ${offeringId} for business: ${businessID}`,
            error?.message
        );
        return undefined;
    }
}

async findAll({ businessID }): Promise<{ data: ReadCustomerResponseData[]; message: string }> {
    CustomerService.logger.log(`Finding customers for ${businessID}`);
    const customerDBModels = await this.InfluxService.getLatestCustomers({ businessID });
    if (customerDBModels.length > 0) {
        const response = [];
        for (let i = 0; i < customerDBModels.length; i++) {
            const dbModel = customerDBModels[i];
            const entity = CustomerEntity.dbModelToEntity(dbModel);
            const { customerId, offeringId } = entity;
            const { data: invoices } = await this.findInvoicesByCustomer({
                customerId,
                businessID,
            });
            const offering = await this.findOfferingForCustomer({ businessID, offeringId });
            response.push(new ReadCustomerResponseData(entity, invoices, offering));
        }
        return {
            data: response,
            message: 'Found Customers',
        };
    } else {
        return { data: [], message: 'No Customers Found' };
    }
}

async findOne({ customerId, businessID }): Promise<{ data: ReadCustomerResponseData[]; message: string }> {
    CustomerService.logger.log(`Finding saasClientID: ${customerId} for ${businessID}`);
    const customerConfig = await this.InfluxService.getLatestCustomer({ businessID, customerId });
    if (customerConfig.length > 0) {
        const { data: invoices } = await this.findInvoicesByCustomer({
            customerId,
            businessID,
        });
        const entity = CustomerEntity.dbModelToEntity(customerConfig[0]);
        const offering = await this.findOfferingForCustomer({ businessID, offeringId: entity.offeringId });
        return {
            data: [new ReadCustomerResponseData(entity, invoices, offering)],
            message: 'Found Customer',
        };
    } else {
        throw new NotFoundException(`Customer with ID: ${customerId} not found`);
    }
}

